def min_moves_to_set_clock(original_time, current_time):
    def time_to_digits(time_str):
        return [int(d) for d in time_str.replace(':', '')]

    def digits_to_time(digits):
        return f"{digits[0]}{digits[1]}:{digits[2]}{digits[3]}"

    def calculate_moves(original_digits, current_digits):
        moves = []
        for i in range(4):
            if original_digits[i] == current_digits[i]:
                continue
            forward_moves = (current_digits[i] - original_digits[i]) % 10
            backward_moves = (original_digits[i] - current_digits[i]) % 10
            if forward_moves <= backward_moves:
                moves.append((forward_moves, i, 1))
            else:
                moves.append((backward_moves, i, -1))
        return moves

    def apply_moves(digits, moves):
        for _, pos, direction in moves:
            digits[pos] = (digits[pos] + direction) % 10
        return digits

    original_digits = time_to_digits(original_time)
    current_digits = time_to_digits(current_time)

    moves = calculate_moves(original_digits, current_digits)
    moves.sort()

    seen_times = set()
    seen_times.add(digits_to_time(original_digits))

    for move_count in range(1, len(moves) + 1):
        for combination in combinations(moves, move_count):
            new_digits = apply_moves(original_digits[:], combination)
            new_time = digits_to_time(new_digits)
            if new_time not in seen_times:
                seen_times.add(new_time)

    seen_times.add(digits_to_time(current_digits))

    print(len(seen_times))
    for time in sorted(seen_times):
        print(time)

